"""L10M closed-loop navigation policy with safety gating, target confirmation,
bounded reacquisition, and hysteresis to reduce oscillation and path waste.
"""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Choose one safe action from the current observation and compact memory.

    The controller confirms a target before moving, pauses briefly after loss,
    steers toward the target with corridor checks, and retains a recent turn
    near neutral bearing to avoid needless left/right instruction flips.
    """
    m = dict(memory or {})
    state = str(m.get("state", "IDLE"))
    scan = str(m.get("scan_direction", "SCAN_LEFT"))
    previous = str(m.get("last_action", ""))
    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    tc = float(observation["target_confidence"])
    ic = float(observation["target_identity_confidence"])
    age = int(observation["track_age"])
    lost = int(observation["lost_steps"])
    safety = float(observation["safety_confidence"])
    risk = float(observation["closing_risk"])

    def emit(action, confidence, next_state):
        m["state"] = next_state
        m["last_action"] = action
        return action, confidence, m

    # Hard safety gate: never trade safety for progress.
    if safety < 0.60 or risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    # Require a sufficiently stable and correctly identified track.
    if not visible or tc < 0.55 or ic < 0.60:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost > 0:
            if lost <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            action = scan
        else:
            action = scan
        m["scan_direction"] = "SCAN_RIGHT" if scan == "SCAN_LEFT" else "SCAN_LEFT"
        return emit(action, 0.74, "SEARCH")

    if age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    # At close range, finish only when both alignment and identity are strong.
    if distance == "near":
        if abs(float(observation["heading_error"])) <= 15.0 and ic >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        turn = "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
        return emit(turn, 0.87, "APPROACH")

    left = bool(observation["corridor_left"])
    right = bool(observation["corridor_right"])
    center = bool(observation["corridor_center"])

    # Use a wider deadband for new turns, but preserve an established turn
    # while the bearing is only mildly corrective (hysteresis).
    if bearing < -12.0 and left:
        action = "VEER_LEFT"
    elif bearing > 12.0 and right:
        action = "VEER_RIGHT"
    elif abs(bearing) <= 18.0 and previous in {"VEER_LEFT", "VEER_RIGHT"}:
        if previous == "VEER_LEFT" and left and bearing < 6.0:
            action = previous
        elif previous == "VEER_RIGHT" and right and bearing > -6.0:
            action = previous
        elif center:
            action = "FORWARD"
        elif left:
            action = "VEER_LEFT"
        elif right:
            action = "VEER_RIGHT"
        else:
            action = "STOP"
    elif center:
        action = "FORWARD"
    elif bearing < 0.0 and left:
        action = "VEER_LEFT"
    elif bearing > 0.0 and right:
        action = "VEER_RIGHT"
    elif left:
        action = "VEER_LEFT"
    elif right:
        action = "VEER_RIGHT"
    else:
        action = "STOP"

    confidence = 0.90 if action in {"FORWARD", "VEER_LEFT", "VEER_RIGHT"} else 0.98
    return emit(action, confidence, "APPROACH" if action != "STOP" else "STOPPED")


# EVOLVE-BLOCK-END
